from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Generator

# Dependency that yields and can exit early
def early_exit_dependency(scope: str) -> Generator[str, None, None]:
    print(f"Dependency started with scope={scope}")
    if scope == "function":
        # Simulate early exit by returning a value instead of yielding
        print("Dependency exiting early (function scope)")
        return "early_exit_value"

    # For "request" scope, it should run fully (yield and finish), and the path operation function should receive the yielded value.
    print("Dependency running fully (request scope)")
    yield "request_value"
    print("Dependency finished (request scope)")

# Path operation function
def read_root(dep_result: str):
    return {"message": f"Received dependency result: {dep_result}"}

# Setup FastAPI app
app = FastAPI()

# Test case 1: scope="function"
@app.get("/function_scope")
def get_function_scope_dep(dep: str = Depends(early_exit_dependency, scope="function")):
    return read_root(dep)

# Test case 2: scope="request" (default)
@app.get("/request_scope")
def get_request_scope_dep(dep: str = Depends(early_exit_dependency, scope="request")):
    return read_root(dep)

# Test case 3: scope="request" (explicit)
@app.get("/request_scope_explicit")
def get_request_scope_explicit_dep(dep: str = Depends(early_exit_dependency, scope="request"):
    return read_root(dep)

client = TestClient(app)

def test_scope_function_early_exit():
    # When scope="function", the dependency should return early, and the path operation function should receive the returned value.
    response = client.get("/function_scope")
    assert response.status_code == 200
    assert response.json() == {"message": "Received dependency result: early_exit_value"}

def test_scope_request_full_cycle():
    # When scope="request", the dependency should run fully (yield and finish), and the path operation function should receive the yielded value.
    response = client.get("/request_scope")
    assert response.status_code == 200
    assert response.json() == {"message": "Received dependency result: request_value"}

def test_scope_request_explicit():
    # Test explicit request scope
    response = client.get("/request_scope_explicit")
    assert response.status_code == 200
    assert response.json() == {"message": "Received dependency result: request_value"}

