from fastapi import APIRouter
from typing import Iterator, Any

router = APIRouter()

def test_iter_route_contexts():
    # Add a dummy route to ensure routes exist
    @router.get("/")
    def read_root():
        return {"Hello": "World"}

    # The method should return an iterator over route contexts
    contexts: Iterator[Any] = router.iter_route_contexts()

    # Check if the iterator yields at least one context
    try:
        first_context = next(contexts)
        assert first_context is not None
        # We can't check the exact structure of the context without knowing the implementation,
        # but we check that iteration works and yields something.
    except StopIteration:
        assert False, "iter_route_contexts() should yield at least one context."

    # Check if it yields all routes (if we had more)
    # For now, just check that it's iterable and yields something.

    # Add another route
    @router.post("/items")
    def create_item():
        return {"message": "item created"}

    # Re-check iteration
    contexts_2: Iterator[Any] = router.iter_route_contexts()
    count = 0
    for _ in contexts_2:
        count += 1

    assert count >= 2, "iter_route_contexts() should yield at least two contexts after adding two routes."

