from fastapi import params
from fastapi.dependencies.utils import get_parameterless_sub_dependant
from fastapi.dependencies.models import Dependant

def test_parameterless_dependency_scope_function():
    # Mock dependency function
    def mock_func():
        return "function_result"

    # Mock params.Depends object that carries scope="function"
    # In a real scenario, params.Depends would be constructed to carry this scope.
    # We simulate this by creating a mock object that has the required attributes.
    class MockDepends:
        def __init__(self, dependency, scope):
            self.dependency = dependency
            self.scope = scope

    mock_dep = MockDepends(dependency=mock_func, scope="function")

    # Test the function under test
    try:
        dependant = get_parameterless_sub_dependant(depends=mock_dep, path="/test")
    except Exception as e:
        assert False, f"get_parameterless_sub_dependant failed: {e}"

    # Assert that the scope was correctly propagated to the Dependant object
    assert dependant.scope == "function", f"Expected scope 'function', but got {dependant.scope}"

def test_parameterless_dependency_scope_request():
    # Mock dependency function
    def mock_func():
        return "request_result"

    # Mock params.Depends object that carries scope="request"
    class MockDepends:
        def __init__(self, dependency, scope):
            self.dependency = dependency
            self.scope = scope

    mock_dep = MockDepends(dependency=mock_func, scope="request")

    # Test the function under test
    try:
        dependant = get_parameterless_sub_dependant(depends=mock_dep, path="/test")
    except Exception as e:
        assert False, f"get_parameterless_sub_dependant failed: {e}"

    # Assert that the scope was correctly propagated to the Dependant object
    assert dependant.scope == "request", f"Expected scope 'request', but got {dependant.scope}"

