from src.requests.utils import _parse_content_type_header

def test_malformed_content_type_parameter():
    # Test case where a parameter is present but lacks '='
    header = "application/json; foo"
    content_type, params = _parse_content_type_header(header)

    assert content_type == "application/json"
    assert params == {}

def test_valid_content_type_parameter():
    # Test case where a parameter is valid
    header = "application/json; charset=utf-8"
    content_type, params = _parse_content_type_header(header)

    assert content_type == "application/json"
    assert params == {"charset": "utf-8"}

def test_malformed_content_type_parameter_with_whitespace():
    # Test case where a parameter is present but lacks '=' and has whitespace
    header = "text/plain;  foo  "
    content_type, params = _parse_content_type_header(header)

    assert content_type == "text/plain"
    assert params == {}

